"""TOST (Two One-Sided Tests) equivalence test for selection F1 vs greedy F1."""
import json, os, sys
import numpy as np
from collections import Counter
from scipy.stats import ttest_1samp

sys.path.insert(0, '/root/autodl-tmp/struct_self_consist_ie/code/')
from consistency import _ner_soft_jaccard_pair, _re_soft_jaccard_pair
from evaluation import per_instance_f1

DATA_PATH = "/root/autodl-tmp/struct_self_consist_ie/output/exp_012_rerun_1024/samples.jsonl"
OUTPUT_PATH = "/root/autodl-tmp/struct_self_consist_ie/output/review_round2/tost_equivalence.json"

def load_instances(path):
    with open(path) as f:
        return [json.loads(line.strip()) for line in f if line.strip()]

def tost(deltas, delta_bound):
    deltas = np.asarray(deltas, dtype=np.float64)
    t1, p1_two = ttest_1samp(deltas, delta_bound)
    p1 = p1_two / 2 if t1 < 0 else 1 - p1_two / 2
    t2, p2_two = ttest_1samp(deltas, -delta_bound)
    p2 = p2_two / 2 if t2 > 0 else 1 - p2_two / 2
    return max(p1, p2)

# --- Per-sample signal scoring functions ---

def per_sample_sj(inst, subtask):
    samples = inst["samples"]
    n = len(samples)
    if n <= 1:
        return [1.0] * n
    if subtask == "ner":
        pair_fn = lambda a, b: _ner_soft_jaccard_pair(a.get("entities", []), b.get("entities", []))
    else:
        pair_fn = lambda a, b: _re_soft_jaccard_pair(a.get("relations", []), b.get("relations", []))
    scores = []
    for k in range(n):
        sims = [pair_fn(samples[k], samples[j]) for j in range(n) if j != k]
        scores.append(float(np.mean(sims)))
    return scores

def per_sample_fk(inst, subtask):
    samples = inst["samples"]
    n = len(samples)
    if n <= 1:
        return [1.0] * n
    if subtask == "ner":
        sample_keys = [{(e["text"], e["type"]) for e in s.get("entities", [])} for s in samples]
    else:
        sample_keys = [{(r["head"], r["tail"], r["type"]) for r in s.get("relations", [])} for s in samples]
    scores = []
    for k in range(n):
        if not sample_keys[k]:
            scores.append(0.0)
            continue
        ent_agr = []
        for key in sample_keys[k]:
            cnt = sum(1 for j in range(n) if j != k and key in sample_keys[j])
            ent_agr.append(cnt / (n - 1))
        scores.append(float(np.mean(ent_agr)))
    return scores

def per_sample_em(inst, subtask):
    samples = inst["samples"]
    n = len(samples)
    if n <= 1:
        return [1.0] * n
    if subtask == "ner":
        sample_sets = [frozenset((e["text"], e["type"], e["start"], e["end"]) for e in s.get("entities", [])) for s in samples]
    else:
        sample_sets = [frozenset((r["head"], r["tail"], r["type"], r.get("head_start"), r.get("head_end"), r.get("tail_start"), r.get("tail_end")) for r in s.get("relations", [])) for s in samples]
    return [sum(1 for j in range(n) if j != k and sample_sets[j] == sample_sets[k]) / (n - 1) for k in range(n)]

def per_sample_logprob(inst, subtask):
    lp = inst.get("logprobs")
    if lp is not None:
        return list(lp)
    return [s.get("mean_logprob", 0.0) for s in inst["samples"]]

def per_sample_voting_conf(inst, subtask):
    samples = inst["samples"]
    n = len(samples)
    if n <= 1:
        return [1.0] * n
    counter = Counter()
    if subtask == "ner":
        for s in samples:
            for e in s.get("entities", []):
                counter[(e["text"], e["type"])] += 1
    else:
        for s in samples:
            for r in s.get("relations", []):
                counter[(r["head"], r["tail"], r["type"])] += 1
    majority_set = {k for k, v in counter.items() if v > n / 2}
    scores = []
    for s in samples:
        if subtask == "ner":
            s_keys = {(e["text"], e["type"]) for e in s.get("entities", [])}
        else:
            s_keys = {(r["head"], r["tail"], r["type"]) for r in s.get("relations", [])}
        overlap = len(s_keys & majority_set)
        penalty = len(s_keys - majority_set)
        scores.append(overlap - 0.5 * penalty)
    return scores

SIGNAL_FNS = {
    "sj": per_sample_sj,
    "fk": per_sample_fk,
    "em": per_sample_em,
    "lp": per_sample_logprob,
    "vc": per_sample_voting_conf,
}
DELTA_BOUNDS = [0.02, 0.03, 0.05]

def analyze_subtask(instances, subtask):
    if subtask == "ner":
        valid = [inst for inst in instances if len(inst["gold"].get("entities", [])) > 0]
    else:
        valid = [inst for inst in instances if len(inst["gold"].get("relations", [])) > 0]

    greedy_f1s = [per_instance_f1(inst.get("greedy", inst["samples"][0]), inst["gold"], subtask=subtask) for inst in valid]
    all_sample_f1s = [[per_instance_f1(s, inst["gold"], subtask=subtask) for s in inst["samples"]] for inst in valid]

    result = {"n": len(valid), "signals": {}}

    for sig_name, sig_fn in SIGNAL_FNS.items():
        sel_f1s = []
        for i, inst in enumerate(valid):
            scores = sig_fn(inst, subtask)
            best_k = int(np.argmax(scores))
            sel_f1s.append(all_sample_f1s[i][best_k])

        deltas = np.array([s - g for s, g in zip(sel_f1s, greedy_f1s)], dtype=np.float64)
        mean_d = float(np.mean(deltas))
        std_d = float(np.std(deltas, ddof=1))

        sig_result = {
            "mean_delta": round(mean_d, 6),
            "std_delta": round(std_d, 6),
            "selection_f1_mean": round(float(np.mean(sel_f1s)), 6),
            "greedy_f1_mean": round(float(np.mean(greedy_f1s)), 6),
        }

        for db in DELTA_BOUNDS:
            p = tost(deltas, db)
            sig_result[f"tost_delta_{db}"] = {
                "p": round(float(p), 6),
                "equivalent": bool(p < 0.05),
            }

        result["signals"][sig_name] = sig_result

    return result

def main():
    instances = load_instances(DATA_PATH)
    print(f"Loaded {len(instances)} instances, N={len(instances[0]['samples'])}")

    results = {}
    for subtask in ["ner", "re"]:
        print(f"\n=== {subtask.upper()} ===")
        results[subtask] = analyze_subtask(instances, subtask)
        print(f"  n={results[subtask]['n']}")
        for sig_name, sig_data in results[subtask]["signals"].items():
            eq_flags = " | ".join(
                f"δ={db}: {'✓' if sig_data[f'tost_delta_{db}']['equivalent'] else '✗'} (p={sig_data[f'tost_delta_{db}']['p']:.4f})"
                for db in DELTA_BOUNDS
            )
            print(f"  {sig_name:>3}: mean_Δ={sig_data['mean_delta']:+.4f} std={sig_data['std_delta']:.4f} | {eq_flags}")

    with open(OUTPUT_PATH, "w") as f:
        json.dump(results, f, indent=2, ensure_ascii=False)
    print(f"\nSaved -> {OUTPUT_PATH}")

    # Summary interpretation
    print("\n" + "="*80)
    print("TOST Equivalence Summary")
    print("="*80)
    for subtask in ["ner", "re"]:
        r = results[subtask]
        print(f"\n{subtask.upper()} (n={r['n']}):")
        for db in DELTA_BOUNDS:
            eq_sigs = [s for s in r["signals"] if r["signals"][s][f"tost_delta_{db}"]["equivalent"]]
            neq_sigs = [s for s in r["signals"] if not r["signals"][s][f"tost_delta_{db}"]["equivalent"]]
            print(f"  δ={db}: equivalent=[{', '.join(eq_sigs) if eq_sigs else 'none'}]  not_confirmed=[{', '.join(neq_sigs) if neq_sigs else 'none'}]")

if __name__ == "__main__":
    main()
